100	func (a errorMsgs) ByType(typ ErrorType) errorMsgs {
101		if len(a) == 0 {
102			return nil
103		}
104		if typ == ErrorTypeAny {
105			return a
106		}
107		var result errorMsgs
108		for _, msg := range a {
109			if msg.IsType(typ) {
