package main

import (
	"fmt"
	"math/rand"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

var statics = []string{"a", "b", "ab", "abc", "user", "x", "user_", "aa"}

type route struct {
	path  string
	conc  string // concrete request path
	names []string
	vals  []string
}

func genRoute(rnd *rand.Rand) route {
	nseg := 1 + rnd.Intn(3)
	var segs []string
	var conc []string
	var names, vals []string
	for i := 0; i < nseg; i++ {
		switch rnd.Intn(4) {
		case 0, 1:
			s := statics[rnd.Intn(len(statics))]
			segs = append(segs, s)
			conc = append(conc, s)
		case 2:
			n := fmt.Sprintf("p%d", i)
			v := fmt.Sprintf("v%d", i)
			segs = append(segs, ":"+n)
			conc = append(conc, v)
			names = append(names, n)
			vals = append(vals, v)
		case 3:
			if i != nseg-1 {
				s := statics[rnd.Intn(len(statics))]
				segs = append(segs, s)
				conc = append(conc, s)
				continue
			}
			n := fmt.Sprintf("c%d", i)
			segs = append(segs, "*"+n)
			conc = append(conc, "w/x")
			names = append(names, n)
			vals = append(vals, "/w/x")
		}
	}
	p := "/" + strings.Join(segs, "/")
	return route{path: p, conc: "/" + strings.Join(conc, "/"), names: names, vals: vals}
}

func main() {
	rnd := rand.New(rand.NewSource(1))
	gin.SetMode(gin.ReleaseMode)
	bad := 0
	for iter := 0; iter < 3000; iter++ {
		// generate a route set
		n := 1 + rnd.Intn(5)
		var rs []route
		seen := map[string]bool{}
		for i := 0; i < n; i++ {
			r := genRoute(rnd)
			if seen[r.path] {
				continue
			}
			seen[r.path] = true
			rs = append(rs, r)
		}
		eng := gin.New()
		ok := true
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					ok = false
				}
			}()
			for _, r := range rs {
				r := r
				eng.GET(r.path, func(c *gin.Context) {
					c.Set("route", r.path)
					c.Set("params", fmt.Sprintf("%v", c.Params))
					c.Set("full", c.FullPath())
				})
			}
		}()
		if !ok {
			continue
		}
		for _, r := range rs {
			w := httptest.NewRecorder()
			req, _ := http.NewRequest("GET", r.conc, nil)
			eng.ServeHTTP(w, req)
			if w.Code != 200 {
				fmt.Printf("MISMATCH status=%d route=%q conc=%q routes=%v\n", w.Code, r.path, r.conc, paths(rs))
				bad++
				continue
			}
			// handler must be the one registered for r.path
			gotRoute := ""
			gotParams := ""
			gotFull := ""
			// re-run to capture via context values
			eng2 := gin.New()
			eng2.GET(r.path, func(c *gin.Context) {
				gotRoute = r.path
				gotParams = fmt.Sprintf("%v", c.Params)
				gotFull = c.FullPath()
			})
			w2 := httptest.NewRecorder()
			eng2.ServeHTTP(w2, req)
			if gotRoute != r.path {
				fmt.Printf("HANDLER MISMATCH route=%q conc=%q\n", r.path, r.conc)
				bad++
			}
			if gotFull != r.path {
				fmt.Printf("FULLPATH MISMATCH route=%q conc=%q got=%q\n", r.path, r.conc, gotFull)
				bad++
			}
			want := ""
			for i, nm := range r.names {
				if i > 0 {
					want += " "
				}
				want += fmt.Sprintf("{%s %s}", nm, r.vals[i])
			}
			if gotParams != want {
				fmt.Printf("PARAM MISMATCH route=%q conc=%q got=%q want=%q\n", r.path, r.conc, gotParams, want)
				bad++
			}
			if bad > 20 {
				fmt.Println("too many, stopping")
				return
			}
		}
	}
	fmt.Println("done, bad =", bad)
}

func paths(rs []route) []string {
	var out []string
	for _, r := range rs {
		out = append(out, r.path)
	}
	return out
}
EOF
