	"fmt"
	"os"

	"github.com/gin-gonic/gin"
)

type customErr struct{ code int }

func (c customErr) Error() string { return fmt.Sprintf("custom error %d", c.code) }

func main() {
	innerErr := errors.New("boom")
	ce := customErr{code: 42}
	fail := 0

	check := func(name string, got, want bool) {
		status := "PASS"
		if got != want {
			status = "FAIL"
			fail++
		}
		fmt.Printf("%-58s %s (got=%v want=%v)\n", name, status, got, want)
	}

	// VALUE gin.Error
	valWrapped := fmt.Errorf("wrapped: %w", gin.Error{Err: innerErr, Type: gin.ErrorTypeAny})
	check("errors.Is(value gin.Error wrapped, innerErr)", errors.Is(valWrapped, innerErr), true)

	// POINTER gin.Error
	ptrWrapped := fmt.Errorf("wrapped: %w", &gin.Error{Err: innerErr, Type: gin.ErrorTypeAny})
	check("errors.Is(pointer gin.Error wrapped, innerErr)", errors.Is(ptrWrapped, innerErr), true)

	// errors.As with custom error type, VALUE
	valCustom := fmt.Errorf("wrapped: %w", gin.Error{Err: ce, Type: gin.ErrorTypeAny})
	var gotVal customErr
	check("errors.As(value gin.Error wrapped, *customErr)", errors.As(valCustom, &gotVal), true)
	if gotVal != ce {
		fmt.Printf("%-58s FAIL (got=%v want=%v)\n", "value customErr payload", gotVal, ce)
		fail++
	}

	// errors.As with custom error type, POINTER
	ptrCustom := fmt.Errorf("wrapped: %w", &gin.Error{Err: ce, Type: gin.ErrorTypeAny})
	var gotPtr customErr
	check("errors.As(pointer gin.Error wrapped, *customErr)", errors.As(ptrCustom, &gotPtr), true)
	if gotPtr != ce {
		fmt.Printf("%-58s FAIL (got=%v want=%v)\n", "pointer customErr payload", gotPtr, ce)
		fail++
	}

	// errors.Unwrap directly
	check("errors.Unwrap(value gin.Error) == innerErr", errors.Unwrap(gin.Error{Err: innerErr, Type: gin.ErrorTypeAny}) == innerErr, true)
	check("errors.Unwrap(pointer gin.Error) == innerErr", errors.Unwrap(&gin.Error{Err: innerErr, Type: gin.ErrorTypeAny}) == innerErr, true)

	fmt.Printf("\nfailures: %d\n", fail)
	if fail > 0 {
		os.Exit(1)
	}
}
