func parsePat(p string) []seg {
	if p == "/" {
		return nil
	}
	parts := strings.Split(p[1:], "/")
	out := make([]seg, 0, len(parts))
	for i, s := range parts {
		switch {
		case strings.HasPrefix(s, ":"):
			out = append(out, seg{1, s[1:]})
		case strings.HasPrefix(s, "*"):
			out = append(out, seg{2, s[1:]})
		default:
			out = append(out, seg{0, s})
		}
		_ = i
	}
	return out
}

func parsePath(p string) []string {
	if p == "/" {
		return nil
	}
	return strings.Split(p[1:], "/")
}

type matchRes struct {
	pat    string
	params []Param
	ok     bool
}

// matchOne tries to match path segments against a pattern.
func matchOne(pat []seg, segs []string) ([]Param, bool) {
	var params []Param
	i := 0
	for ; i < len(pat); i++ {
		s := pat[i]
		if s.kind == 2 { // catchAll: needs at least one remaining segment
			if i >= len(segs) {
				return nil, false
			}
			params = append(params, Param{s.val, "/" + strings.Join(segs[i:], "/")})
			return params, true
		}
		if i >= len(segs) {
			return nil, false
		}
		if s.kind == 0 {
			if segs[i] != s.val {
				return nil, false
			}
		} else { // param: non-empty segment
			if segs[i] == "" {
				return nil, false
			}
			params = append(params, Param{s.val, segs[i]})
		}
	}
	if i != len(segs) {
		return nil, false
	}
	return params, true
}

func typeSeq(pat []seg) []int {
	out := make([]int, len(pat))
	for i, s := range pat {
		out[i] = s.kind
	}
	return out
}

func lessType(a, b []int) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return len(a) < len(b)
}

func reference(patterns []string, path string) matchRes {
	segs := parsePath(path)
