// checkConsistency verifies that the params returned for a matched route are
// exactly the segments of the request path as described by the route pattern.
func checkConsistency(t *testing.T, pats []string, path, fullPath string, got []Param) bool {
	segs := parsePath(path)
	ps := parsePat(fullPath)
	var want []Param
	i := 0
	for ; i < len(ps); i++ {
		s := ps[i]
		if s.kind == 2 {
			want = append(want, Param{s.val, "/" + strings.Join(segs[i:], "/")})
			i = len(segs)
			break
		}
		if i >= len(segs) {
			t.Errorf("INCONSISTENT pats=%v path=%q fullPath=%q params=%v (pattern longer than path)", pats, path, fullPath, got)
			return false
		}
		if s.kind == 0 {
			if segs[i] != s.val {
				t.Errorf("INCONSISTENT pats=%v path=%q fullPath=%q params=%v (static seg %q != %q)", pats, path, fullPath, got, segs[i], s.val)
				return false
			}
		} else {
			want = append(want, Param{s.val, segs[i]})
		}
	}
	if i != len(segs) {
		t.Errorf("INCONSISTENT pats=%v path=%q fullPath=%q params=%v (path longer than pattern)", pats, path, fullPath, got)
		return false
	}
	if !paramsEqual(got, want) {
		t.Errorf("PARAMS WRONG pats=%v path=%q fullPath=%q got=%v want=%v", pats, path, fullPath, got, want)
		return false
	}
	return true
}

